#include "stdlib/blas/ext/base/cnancount.h"
#include "stdlib/complex/float32/ctor.h"
#include <stdio.h>

int main( void ) {
	// Create a strided array:
	const stdlib_complex64_t x[] = {
		stdlib_complex64( 1.0f, 2.0f ),
		stdlib_complex64( 3.0f, 4.0f ),
		stdlib_complex64( 0.0f/0.0f, 5.0f ), // NaN
		stdlib_complex64( 6.0f, 0.0f/0.0f ), // NaN
		stdlib_complex64( 7.0f, 8.0f )
	};

	// Specify the number of indexed elements:
	const int N = 5;

	// Specify the stride length:
	const int strideX = 1;

	// Compute the number of non-NaN elements:
	int v = stdlib_strided_cnancount( N, x, strideX );

	// Print the result:
	printf( "count: %d\n", v );
}
